class Solution { public: long long minCost(vector<int>& arr, vector<int>& brr, long long k) {
 long long direct=0,sorted=k; for(int i=0;i<(int)arr.size();++i) direct+=abs((long long)arr[i]-brr[i]);
 sort(arr.begin(),arr.end());sort(brr.begin(),brr.end()); for(int i=0;i<(int)arr.size();++i) sorted+=abs((long long)arr[i]-brr[i]);return min(direct,sorted);
}};
